-- Добавляет изображения событий из открытых Wikimedia-источников.
-- Диапазон id отделен от базовых seed-данных, чтобы миграцию можно было применять повторно.
DELETE FROM media WHERE id BETWEEN 1010 AND 1012;
DELETE FROM media WHERE id BETWEEN 4000 AND 5099;

ON CONFLICT (id) DO UPDATE
SET event_id = EXCLUDED.event_id,
    url = EXCLUDED.url,
    caption = EXCLUDED.caption,
    type = EXCLUDED.type;

SELECT setval('media_id_seq', (SELECT max(id) FROM media));
